mapper.select:
WITH inserted AS (
	INSERT INTO ai_report (campaign_id, report_type, input_json, content, model)
	VALUES (#{campaignId}, #{reportType}, CAST(#{inputJson} AS jsonb), #{content}, #{model})
	RETURNING report_id
), trimmed AS (
	DELETE FROM ai_report
	WHERE campaign_id = #{campaignId} AND report_type = #{reportType}
	  AND report_id NOT IN (
	      SELECT report_id FROM ai_report
	      WHERE campaign_id = #{campaignId} AND report_type = #{reportType}
	      ORDER BY report_id DESC
	      LIMIT #{keep} - 1
	  )
)
SELECT report_id FROM inserted
